$ultimateGuid = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
# powercfg gives every copy of the Ultimate scheme a new random GUID, so the copy is renamed to a
# fixed name and found by it on later runs instead of piling up another duplicate each time
$planName = 'MejorarWindows Ultimate Performance'
$guidPattern = '[A-Fa-f0-9]{8}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{12}'
$existing = @(powercfg /list) | Where-Object { $_ -match [regex]::Escape($planName) -or $_ -match $ultimateGuid } | Select-Object -First 1
if ($existing -and $existing -match $guidPattern) {
    $planGuid = $matches[0]
} else {
    $output = (powercfg /duplicatescheme $ultimateGuid) | Out-String
    if ($LASTEXITCODE -ne 0 -or -not ($output -match $guidPattern)) {
        throw "powercfg could not duplicate the Ultimate Performance scheme (exit code $LASTEXITCODE)."
    }
    $planGuid = $matches[0]
    powercfg /changename $planGuid $planName | Out-Null
}
powercfg /setactive $planGuid
if ($LASTEXITCODE -ne 0) {
    throw "powercfg could not activate the Ultimate Performance scheme (exit code $LASTEXITCODE)."
}

