$planName = 'MejorarWindows Ultimate Performance'
$guidPattern = '[A-Fa-f0-9]{8}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{12}'
# Back to Balanced first: powercfg refuses to delete the active plan
powercfg /setactive 381b4222-f694-41f0-9685-ff5bb260df2e
@(powercfg /list) | Where-Object { $_ -match [regex]::Escape($planName) } | ForEach-Object {
    if ($_ -match $guidPattern) {
        powercfg /delete $matches[0] | Out-Null
    }
}

